namespace GlpiPlugin\Pdf\Tests;

use PluginPdfSimplePDF;

class RecordingSimplePDF extends PluginPdfSimplePDF
{
    /** @var string[] */
    public array $cells = [];

    public function __construct()
    {
        parent::__construct();
        $this->newPage();
    }

    public function displayTitle()
    {
        array_push($this->cells, ...func_get_args());
        parent::displayTitle(...func_get_args());
    }

    public function displayLine()
    {
        array_push($this->cells, ...func_get_args());
        parent::displayLine(...func_get_args());
    }
}
